// TypeScript Version: 4.1

/**
* Evaluates the complementary error function for a single-precision floating-point number.
*
* ## Notes
*
* -   The complementary error function is defined as
*
*     ```tex
*     \operatorname{erfc}(x) = 1 - \operatorname{erf}(x) = \frac{2}{\sqrt{\pi}} \int_x^\infty e^{-t^2}\,\mathrm{d}t
*     ```
*
* @param x - input value
* @returns function value
*
* @example
* var y = erfcf( 0.0 );
* // returns 1.0
*
* @example
* var y = erfcf( 1.0 );
* // returns ~0.1573
*
* @example
* var y = erfcf( -1.0 );
* // returns ~1.8427
*
* @example
* var y = erfcf( Infinity );
* // returns 0.0
*
* @example
* var y = erfcf( -Infinity );
* // returns 2.0
*
* @example
* var y = erfcf( NaN );
* // returns NaN
*/
declare function erfcf( x: number ): number;


// EXPORTS //

export = erfcf;